%%\ Option A — Compare Denoising Filters
close all; clear; clc;

% 1. Load reference image and add deterministic mixed noise
Iref = imread('rice.png');
rng(42);
Id = imnoise(imnoise(Iref, 'gaussian', 0, 0.01), 'salt & pepper', 0.02);

% 2. Apply the three denoising filters
I_med       = medfilt2(Id, [3 3]);
I_gauss     = imgaussfilt(Id, 1.5);
I_med_gauss = imgaussfilt(medfilt2(Id, [3 3]), 1);

% Save the three processed images (required for results/ folder)
imwrite(I_med,       'denoised_median_3x3.png');
imwrite(I_gauss,     'denoised_gaussian_sigma1_5.png');
imwrite(I_med_gauss, 'denoised_median_then_gaussian.png');

% 3. Compute PSNR and SSIM against Iref and display table
Method = { ...
    'Degraded (Gaussian + Salt & Pepper)'; ...
    'Median (3x3)'; ...
    'Gaussian (sigma = 1.5)'; ...
    'Median (3x3) + Gaussian (sigma = 1)'};

PSNR_dB = [psnr(Id, Iref); psnr(I_med, Iref); psnr(I_gauss, Iref); psnr(I_med_gauss, Iref)];
SSIM    = [ssim(Id, Iref); ssim(I_med, Iref); ssim(I_gauss, Iref); ssim(I_med_gauss, Iref)];

resultsTable = table(Method, round(PSNR_dB, 4), round(SSIM, 4), ...
    'VariableNames', {'Method', 'PSNR_dB', 'SSIM'});
disp(resultsTable); %[output:35002edf]

% 4. Full images and zoomed 80x80 region comparison
figure('Name', 'Full Comparison'); %[output:1f2f3c41]
montage({Iref, Id, I_med, I_gauss, I_med_gauss}, 'Size', [1 5]); %[output:1f2f3c41]
title('Reference | Degraded | Median 3x3 | Gaussian \sigma=1.5 | Median + Gaussian \sigma=1'); %[output:1f2f3c41]

r = 80:159; % 80x80 zoomed region (>= 60x60)
c = 80:159;
figure('Name', 'Zoomed 80x80 Region'); %[output:7bdec9ab]
montage({Iref(r,c), Id(r,c), I_med(r,c), I_gauss(r,c), I_med_gauss(r,c)}, 'Size', [1 5]); %[output:7bdec9ab]
title('Zoom 80x80: Reference | Degraded | Median 3x3 | Gaussian \sigma=1.5 | Median + Gaussian \sigma=1'); %[output:7bdec9ab]



% 
% Preferred Filter and Visual Analysis (80x80 Zoomed Region):
% The cascaded filter (3x3 Median followed by Gaussian with sigma = 1) is the preferred choice for this mixed-noise scenario, achieving the highest PSNR and SSIM scores as well as the cleanest visual appearance in the 80x80 zoomed crop:
% 1. 3x3 Median filter alone: Effectively removes isolated salt-and-pepper impulses and preserves sharp rice-grain edges, but leaves noticeable residual granular fluctuations (Gaussian noise) across both the dark background and grain interiors.
% 2. Gaussian filter (sigma = 1.5) alone: Smooths continuous Gaussian noise, but smears extreme salt-and-pepper impulses into visible gray/white blotches and noticeably blurs rice-grain boundaries.
% 3. Cascade (3x3 Median + Gaussian sigma = 1): Combines the strengths of both stages. The non-linear median filter first rejects impulse outliers without spreading their energy, allowing the subsequent mild Gaussian filter (sigma = 1) to suppress residual Gaussian noise with minimal edge blur (only slight softening of the sharpest grain tips).
% 
% Limitation of the Comparison:
% PSNR and SSIM are global, full-reference summary metrics averaged equally across all 256 x 256 pixels. Because smooth dark background pixels occupy most of the frame, global metrics under-emphasize localized edge degradation and do not directly measure task-specific performance (such as downstream binary segmentation or grain-count accuracy). In addition, real-world sensor noise parameters and degradation order are typically unknown a priori.


